-- 0001_init.sql
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- ROLES
CREATE TABLE
    role (
        id SMALLINT PRIMARY KEY,
        name TEXT UNIQUE NOT NULL
    );

INSERT INTO
    role (id, name)
VALUES
    (1, 'admin'),
    (2, 'manager'),
    (3, 'sales_associate') ON CONFLICT DO NOTHING;

-- APP USERS
CREATE TABLE
    app_user (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid (), -- surrogate PK (autogenerated)
        username TEXT UNIQUE NOT NULL, -- login name (NOT the PK)
        password_hash TEXT NOT NULL,
        first_name TEXT NOT NULL,
        middle_name TEXT,
        last_name TEXT NOT NULL,
        street_address TEXT,
        suite_number TEXT,
        city TEXT,
        state_us TEXT,
        zip_code TEXT,
        phone_number TEXT,
        birth_date DATE,
        starting_date DATE NOT NULL DEFAULT CURRENT_DATE,
        terminated_date DATE,
        is_active BOOLEAN NOT NULL DEFAULT TRUE,
        created_at TIMESTAMPTZ NOT NULL DEFAULT now (),
        updated_at TIMESTAMPTZ NOT NULL DEFAULT now ()
    );

CREATE INDEX IF NOT EXISTS app_user_name_idx ON app_user (last_name, first_name);

-- USER ↔ ROLE (many-to-many)
CREATE TABLE
    app_user_role (
        user_id UUID REFERENCES app_user (id) ON DELETE CASCADE,
        role_id SMALLINT REFERENCES role (id) ON DELETE RESTRICT,
        PRIMARY KEY (user_id, role_id)
    );

-- SESSIONS
CREATE TABLE
    session (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid (),
        user_id UUID NOT NULL REFERENCES app_user (id) ON DELETE CASCADE,
        created_at TIMESTAMPTZ NOT NULL DEFAULT now (),
        expires_at TIMESTAMPTZ NOT NULL,
        last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now ()
    );

CREATE INDEX IF NOT EXISTS session_user_idx ON session (user_id);

-- CUSTOMER (normalized snake_case; optional but recommended)
CREATE TABLE
    customer (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid (),
        first_name TEXT NOT NULL,
        middle_name TEXT,
        last_name TEXT NOT NULL,
        suffix TEXT,
        date_of_birth DATE NOT NULL,
        sex TEXT,
        eye_color TEXT,
        height TEXT,
        street_address TEXT,
        city TEXT,
        state_us TEXT,
        zipcode TEXT,
        id_number TEXT,
        id_expiration DATE,
        id_issue_date DATE,
        issuing_state TEXT,
        phone_number TEXT,
        email TEXT,
        created_at TIMESTAMPTZ NOT NULL DEFAULT now (),
        updated_at TIMESTAMPTZ NOT NULL DEFAULT now ()
    );

CREATE INDEX IF NOT EXISTS customer_name_idx ON customer (last_name, first_name);

CREATE INDEX IF NOT EXISTS customer_dob_idx ON customer (date_of_birth);

